import { createButton, createStatePanel } from '../../components/ui.js';

function getDocument(documentRef) {
  const doc = documentRef || globalThis.document;
  if (!doc?.createElement) throw new Error('document kerak');
  return doc;
}
function el(doc, tag, className = '', text = null) {
  const n = doc.createElement(tag);
  if (className) n.className = className;
  if (text != null) n.textContent = String(text);
  return n;
}
function nameControl(control, label) {
  if (control?.setAttribute && label) control.setAttribute('aria-label', String(label));
  return control;
}
function list(value) { return Array.isArray(value) ? value.filter(Boolean) : []; }
function text(value, fallback = '—') { const s = String(value ?? '').trim(); return s || fallback; }
function money(value) { return `${new Intl.NumberFormat('uz-UZ').format(Number(value || 0))} so‘m`; }
function date(value) { if (!value) return '—'; const d = new Date(value); return Number.isNaN(d.getTime()) ? '—' : new Intl.DateTimeFormat('uz-UZ', { day:'2-digit', month:'short', year:'numeric' }).format(d); }
function dateTime(value) { if (!value) return '—'; const d = new Date(value); return Number.isNaN(d.getTime()) ? '—' : new Intl.DateTimeFormat('uz-UZ', { day:'2-digit', month:'short', year:'numeric', hour:'2-digit', minute:'2-digit' }).format(d); }
function statusTone(value) { const s=String(value||'').toUpperCase(); if(['ACTIVE','APPROVED','ANSWERED'].includes(s)) return 'success'; if(['NEW','FROZEN','PROVISIONING','PENDING'].includes(s)) return 'warning'; if(['TERMINATED','REJECTED','ERROR','CLOSED'].includes(s)) return 'danger'; return 'neutral'; }
function statusLabel(value) { const s=String(value||'').toUpperCase(); return ({ACTIVE:'Faol',FROZEN:'Muzlatilgan',TERMINATED:"O‘chirilgan",PROVISIONING:'Sozlanmoqda',NEW:'Yangi',APPROVED:'Tasdiqlangan',REJECTED:'Rad etilgan',OPEN:'Ochiq',ANSWERED:'Javob berilgan',CLOSED:'Yopilgan'})[s] || s || 'Noma’lum'; }
function badge(doc, label, tone='neutral') { return el(doc, 'span', `uw-platform-badge uw-platform-badge--${tone}`, label); }
function safeUrl(value) { try { const u = new URL(String(value||'')); return ['https:','http:'].includes(u.protocol) ? u.href : ''; } catch { return ''; } }
function createStore(initial) {
  let state = Object.freeze(initial); const listeners = new Set();
  return { get:()=>state, set:(patch)=>{ state=Object.freeze({...state,...patch}); for(const fn of listeners) fn(state); return state; }, subscribe:(fn)=>{listeners.add(fn); return ()=>listeners.delete(fn);} };
}
function localFail(message='Bu amal faqat platforma Super Admin uchun.') { return { ok:false, error:{ code:'FORBIDDEN', message } }; }
function normalizeShop(row) { if(!row?.id) return null; return {...row,id:String(row.id),status:String(row.status||'UNKNOWN').toUpperCase()}; }
function normalizeRequest(row) { if(!row?.id) return null; return {...row,id:String(row.id),status:String(row.status||'UNKNOWN').toUpperCase(),tariffPrice:Number(row.tariffPrice||0)}; }
function normalizeTariff(row) { if(!row?.id)return null; return {...row,id:String(row.id),price:Number(row.price||0),productLimit:row.productLimit==null?null:Number(row.productLimit),features:list(row.features).map(String)}; }

export function createPlatformAdminController({ platformPort, authPort = null } = {}) {
  if (!platformPort?.invoke) throw new TypeError('platformPort kerak');
  const store = createStore({
    status:'idle', error:null, actor:null, isSuperAdmin:false, notice:null, mutationStatus:null,
    dashboardStatus:'idle', dashboard:null,
    shopsStatus:'idle', shops:[], selectedShopId:null, shopHistory:[], shopActions:[], shopQuery:'', shopStatusFilter:'ALL',
    requestsStatus:'idle', requests:[], requestStatusFilter:'ALL', selectedRequestId:null, requestHistory:[], requestDetail:null,
    supportStatus:'idle', tickets:[], supportStatusFilter:'OPEN', selectedTicketId:null, messages:[],
    tariffsStatus:'idle', tariffs:[],
    analyticsStatus:'idle', analytics:null, analyticsPeriod:'30d',
    settingsStatus:'idle', lifecycleSettings:null, paymentInfo:null, paymentMethods:[], notificationTemplates:[],
  });
  let shopView=0, requestView=0, ticketView=0;
  const invoke=(action,payload={})=>platformPort.invoke(action,payload);
  const setNotice=(kind,message)=>store.set({notice:message?{kind,message}:null});
  const canAdmin=()=>store.get().status==='ready' && store.get().isSuperAdmin===true;
  async function requireAdminInvoke(action,payload={}) { if(!canAdmin()) return localFail(); return invoke(action,payload); }

  async function load() {
    store.set({status:'loading',error:null});
    const r=await invoke('platform_boot',{});
    if(!r.ok){store.set({status:'error',error:r.error||{message:'Platforma yuklanmadi.'}});return r;}
    const isSuperAdmin=r.data?.isSuperAdmin===true || r.data?.platformActor?.platformRole==='SUPER_ADMIN';
    if(!isSuperAdmin){store.set({status:'forbidden',error:null,actor:r.data?.platformActor||null,isSuperAdmin:false});return localFail();}
    store.set({status:'ready',error:null,actor:r.data?.platformActor||null,isSuperAdmin:true});
    return r;
  }
  async function loadDashboard(){if(!canAdmin())return localFail();store.set({dashboardStatus:'loading'});const r=await requireAdminInvoke('platform_admin_dashboard_summary',{});store.set(r.ok?{dashboardStatus:'ready',dashboard:r.data}:{dashboardStatus:'error'});return r;}
  async function loadShops({shopId=null}={}){if(!canAdmin())return localFail();store.set({shopsStatus:'loading'});const r=await requireAdminInvoke('platform_list_shops',{});if(!r.ok){store.set({shopsStatus:'error'});return r;}const shops=list(r.data?.shops).map(normalizeShop).filter(Boolean);const current=shopId?String(shopId):store.get().selectedShopId;const selected=shops.some(s=>s.id===current)?current:(shops[0]?.id||null);store.set({shopsStatus:'ready',shops,selectedShopId:selected});if(shopId)await loadShopDetail(shopId,{skipList:true});return r;}
  async function loadShopDetail(shopId,{skipList=false}={}){const view=++shopView;const id=String(shopId||'');if(!id)return {ok:false,error:{code:'VALIDATION_ERROR',message:"Do‘kon tanlanmagan."}};if(!canAdmin())return localFail();if(!skipList&&!store.get().shops.length){const lr=await loadShops();if(!lr.ok)return lr;}if(view!==shopView)return {ok:false,error:{code:'CONFLICT',message:'Selection changed',retryable:false}};store.set({selectedShopId:id,shopHistory:[],shopActions:[]});const [history,actions]=await Promise.all([requireAdminInvoke('platform_list_subscription_history',{shopId:id}),requireAdminInvoke('platform_list_shop_admin_actions',{shopId:id})]);if(view!==shopView)return {ok:false,error:{code:'CONFLICT',message:'Selection changed',retryable:false}};store.set({shopHistory:history.ok?list(history.data?.history):[],shopActions:actions.ok?list(actions.data?.actions):[]});return history.ok||actions.ok?{ok:true,data:{}}:(history.ok?actions:history);}
  async function loadRequests({status=store.get().requestStatusFilter,requestId=null}={}){if(!canAdmin())return localFail();const normalized=['NEW','APPROVED','REJECTED'].includes(String(status))?String(status):'ALL';store.set({requestsStatus:'loading',requestStatusFilter:normalized});const r=await requireAdminInvoke('platform_list_subscription_requests',normalized==='ALL'?{}:{status:normalized});if(!r.ok){store.set({requestsStatus:'error'});return r;}const requests=list(r.data?.requests).map(normalizeRequest).filter(Boolean);store.set({requestsStatus:'ready',requests});if(requestId)await loadRequestDetail(requestId);return r;}
  async function loadRequestDetail(requestId){const view=++requestView;const id=String(requestId||'');if(!id)return {ok:false,error:{code:'VALIDATION_ERROR',message:'Ariza tanlanmagan.'}};if(!canAdmin())return localFail();store.set({selectedRequestId:id,requestHistory:[],requestDetail:null});const r=await requireAdminInvoke('platform_get_subscription_request_history',{requestId:id});if(view!==requestView)return r;if(r.ok)store.set({requestDetail:normalizeRequest(r.data?.request),requestHistory:list(r.data?.history)});return r;}
  async function loadSupport({status=store.get().supportStatusFilter,ticketId=null}={}){if(!canAdmin())return localFail();const normalized=['OPEN','ANSWERED','CLOSED'].includes(String(status))?String(status):'ALL';store.set({supportStatus:'loading',supportStatusFilter:normalized});const r=await requireAdminInvoke('platform_admin_list_support_tickets',normalized==='ALL'?{}:{status:normalized});if(!r.ok){store.set({supportStatus:'error'});return r;}store.set({supportStatus:'ready',tickets:list(r.data?.tickets)});if(ticketId)await openTicket(ticketId);return r;}
  async function openTicket(ticketId){const view=++ticketView;const id=Number(ticketId);if(!Number.isInteger(id)||id<=0)return {ok:false,error:{code:'VALIDATION_ERROR',message:'Murojaat tanlanmagan.'}};if(!canAdmin())return localFail();store.set({selectedTicketId:id,messages:[]});const r=await requireAdminInvoke('platform_get_support_messages',{ticketId:id});if(view!==ticketView)return r;if(r.ok)store.set({messages:list(r.data?.messages)});return r;}
  async function loadTariffs(){if(!canAdmin())return localFail();store.set({tariffsStatus:'loading'});const r=await requireAdminInvoke('platform_admin_list_tariffs',{});store.set(r.ok?{tariffsStatus:'ready',tariffs:list(r.data?.tariffs).map(normalizeTariff).filter(Boolean)}:{tariffsStatus:'error'});return r;}
  async function loadAnalytics(period=store.get().analyticsPeriod){if(!canAdmin())return localFail();const p=['7d','30d','90d','all'].includes(String(period))?String(period):'30d';store.set({analyticsStatus:'loading',analyticsPeriod:p});const r=await requireAdminInvoke('platform_admin_analytics_summary',{period:p});store.set(r.ok?{analyticsStatus:'ready',analytics:r.data}:{analyticsStatus:'error'});return r;}
  async function loadSettings(){if(!canAdmin())return localFail();store.set({settingsStatus:'loading'});const [life,card,methods,templates]=await Promise.all([requireAdminInvoke('platform_get_lifecycle_settings',{}),requireAdminInvoke('platform_get_payment_info',{}),requireAdminInvoke('platform_admin_list_payment_methods',{}),requireAdminInvoke('platform_admin_list_notification_templates',{})]);const okAny=life.ok||card.ok||methods.ok||templates.ok;store.set({settingsStatus:okAny?'ready':'error',lifecycleSettings:life.ok?life.data?.settings:null,paymentInfo:card.ok?card.data:null,paymentMethods:methods.ok?list(methods.data?.methods):[],notificationTemplates:templates.ok?list(templates.data?.templates):[]});return okAny?{ok:true,data:{}}:(life.ok?card:life);}
  async function loadSection(section,params={}){if(store.get().status==='idle'||store.get().status==='error')await load();if(!canAdmin())return localFail();if(section==='shops')return loadShops({shopId:params.shopId||null});if(section==='requests')return loadRequests({requestId:params.requestId||null});if(section==='support')return loadSupport({ticketId:params.ticketId||null});if(section==='tariffs')return loadTariffs();if(section==='analytics')return loadAnalytics();if(section==='settings')return loadSettings();return loadDashboard();}
  async function mutate(key,action,payload,onSuccess,message){if(!canAdmin())return localFail();store.set({mutationStatus:key});try{const r=await requireAdminInvoke(action,payload);if(r.ok){setNotice('success',message||'Amal bajarildi.');if(onSuccess)await onSuccess(r);}else setNotice('error',r.error?.message||'Amal bajarilmadi.');return r;}finally{store.set({mutationStatus:null});}}
  const refreshShop=async(id)=>{await loadShops();if(id)await loadShopDetail(id,{skipList:true});};
  function setShopQuery(value){store.set({shopQuery:String(value||'')});}
  function setShopStatusFilter(value){store.set({shopStatusFilter:['ALL','ACTIVE','FROZEN','PROVISIONING','TERMINATED'].includes(String(value))?String(value):'ALL'});}
  async function setIntegrationAccess(shopId,kind,enabled){const map={billz:'platform_set_billz_access',click:'platform_set_click_access',payme:'platform_set_payme_access',uzum:'platform_set_uzum_access'};const action=map[String(kind||'').toLowerCase()];if(!action)return {ok:false,error:{code:'VALIDATION_ERROR',message:'Integratsiya turi noto‘g‘ri.'}};return mutate(`access:${kind}`,action,{shopId:String(shopId),enabled:enabled===true},()=>refreshShop(shopId),'Integratsiya ruxsati yangilandi.');}
  async function grantDays(shopId,days,reason){return mutate('grant-days','platform_grant_subscription_days',{shopId:String(shopId),days:Number(days),reason:String(reason||'')},()=>refreshShop(shopId),'Obuna muddati yangilandi.');}
  async function freezeShop(shopId,reason){return mutate('freeze','platform_freeze_shop',{shopId:String(shopId),reason:String(reason||'')},()=>refreshShop(shopId),"Do‘kon muzlatildi.");}
  async function reactivateShop(shopId){return mutate('reactivate','platform_reactivate_shop',{shopId:String(shopId)},()=>refreshShop(shopId),"Do‘kon qayta faollashtirildi.");}
  async function extendFrozenGrace(shopId,days,reason){return mutate('extend-grace','platform_extend_frozen_grace',{shopId:String(shopId),days:Number(days),reason:String(reason||'')},()=>refreshShop(shopId),'Saqlash muddati uzaytirildi.');}
  async function terminateShop(shopId,reason){return mutate('terminate','platform_terminate_shop',{shopId:String(shopId),reason:String(reason||'')},async(r)=>{await loadShops();store.set({selectedShopId:null,shopHistory:[],shopActions:[]});if(r.data?.backupDownloadUrl)setNotice('warning',"Do‘kon o‘chirildi. Backup havolasi vaqtinchalik — darhol saqlang.");},"Do‘kon o‘chirildi.");}
  async function approveRequest(requestId){return mutate('approve-request','platform_approve_subscription_request',{requestId:String(requestId)},async()=>{await loadRequests({status:store.get().requestStatusFilter,requestId});},'To‘lov tasdiqlandi.');}
  async function rejectRequest(requestId,reason){return mutate('reject-request','platform_reject_subscription_request',{requestId:String(requestId),reason:String(reason||'')},async()=>{await loadRequests({status:store.get().requestStatusFilter,requestId});},'Ariza rad etildi.');}
  async function provisionShop(requestId,botToken){const secret=String(botToken||'').trim();if(!secret)return {ok:false,error:{code:'VALIDATION_ERROR',message:'Bot token kerak.'}};return mutate('provision','platform_provision_shop_from_request',{requestId:String(requestId),botToken:secret},async()=>{await Promise.all([loadRequests({status:store.get().requestStatusFilter,requestId}),loadShops()]);},"Do‘kon yaratish oqimi bajarildi.");}
  async function getReceiptUrl(requestId){return requireAdminInvoke('platform_get_subscription_receipt_url',{requestId:String(requestId)});}
  async function getBotPhotoUrl(requestId){return requireAdminInvoke('platform_get_bot_photo_url',{requestId:String(requestId)});}
  async function sendSupportMessage(ticketId,body){const value=String(body||'').trim();if(!value)return {ok:false,error:{code:'VALIDATION_ERROR',message:'Xabarni kiriting.'}};return mutate('support-send','platform_send_support_message',{ticketId:Number(ticketId),body:value},async()=>{await openTicket(ticketId);await loadSupport({status:store.get().supportStatusFilter});store.set({selectedTicketId:Number(ticketId)});},'Javob yuborildi.');}
  async function closeSupportTicket(ticketId){return mutate('support-close','platform_close_support_ticket',{ticketId:Number(ticketId)},async()=>{await loadSupport({status:store.get().supportStatusFilter});store.set({selectedTicketId:null,messages:[]});},'Murojaat yopildi.');}
  async function saveTariff(payload){const clean={...payload,id:payload?.id?String(payload.id):undefined,name:String(payload?.name||'').trim(),price:Number(payload?.price),productLimit:payload?.productLimit===''?null:payload?.productLimit==null?null:Number(payload.productLimit),sortOrder:Number(payload?.sortOrder||0),isActive:payload?.isActive!==false,isPopular:payload?.isPopular===true,features:list(payload?.features).map(x=>String(x).trim()).filter(Boolean)};return mutate('tariff','platform_upsert_tariff',clean,()=>loadTariffs(),'Tarif saqlandi.');}
  async function saveLifecycleSettings(payload){return mutate('lifecycle','platform_update_lifecycle_settings',payload,()=>loadSettings(),'Lifecycle sozlamalari saqlandi.');}
  async function savePaymentInfo(payload){return mutate('payment-card','platform_set_payment_info',{cardNumber:String(payload?.cardNumber||''),cardHolder:String(payload?.cardHolder||''),isActive:payload?.isActive!==false},()=>loadSettings(),'To‘lov kartasi saqlandi.');}
  async function savePaymentMethod(payload){return mutate('payment-method','platform_upsert_payment_method',{...payload,id:payload?.id?String(payload.id):undefined,methodType:String(payload?.methodType||'').toUpperCase(),displayName:String(payload?.displayName||''),paymentUrl:String(payload?.paymentUrl||''),isActive:payload?.isActive!==false,sortOrder:Number(payload?.sortOrder||0)},()=>loadSettings(),'To‘lov usuli saqlandi.');}
  async function saveNotificationTemplate(payload){return mutate('notification','platform_update_notification_template',{...payload,type:String(payload?.type||''),body:String(payload?.body||''),imageUrl:String(payload?.imageUrl||'')||null,isActive:payload?.isActive!==false},()=>loadSettings(),'Xabar shabloni saqlandi.');}
  async function sendTestNotification(type){return mutate('notification-test','platform_send_test_notification',{type:String(type||'')},null,'Sinov xabari Super Admin akkauntiga yuborildi.');}
  async function setupPlatformBot(){return mutate('platform-setup','platform_setup',{},null,'Platform bot konfiguratsiyasi bajarildi.');}
  async function signOut(){if(!authPort?.signOut)return {ok:false,error:{code:'UNAVAILABLE',message:'Chiqish mavjud emas.'}};const r=await authPort.signOut();if(r.ok)store.set({status:'idle',actor:null,isSuperAdmin:false});return r;}

  return Object.freeze({
    getState:store.get,subscribe:store.subscribe,load,loadSection,loadDashboard,loadShops,loadShopDetail,loadRequests,loadRequestDetail,loadSupport,openTicket,loadTariffs,loadAnalytics,loadSettings,
    setShopQuery,setShopStatusFilter,setIntegrationAccess,grantDays,freezeShop,reactivateShop,extendFrozenGrace,terminateShop,approveRequest,rejectRequest,provisionShop,getReceiptUrl,getBotPhotoUrl,
    sendSupportMessage,closeSupportTicket,saveTariff,saveLifecycleSettings,savePaymentInfo,savePaymentMethod,saveNotificationTemplate,sendTestNotification,setupPlatformBot,signOut,setNotice,
  });
}

const ADMIN_NAV=[
  ['overview','Umumiy','/platform/admin'],['shops',"Do‘konlar",'/platform/admin/shops'],['requests','Arizalar','/platform/admin/requests'],['support','Support','/platform/admin/support'],['tariffs','Tariflar','/platform/admin/tariffs'],['analytics','Analitika','/platform/admin/analytics'],['settings','Sozlamalar','/platform/admin/settings'],
];
function adminHeader(doc,state,{onNavigate,onLogout}){const h=el(doc,'header','uw-platform-admin__header');const brand=el(doc,'button','uw-platform-admin__brand');brand.type='button';brand.append(el(doc,'span','uw-platform-admin__mark','U'),el(doc,'span','','UStorE'),badge(doc,'SUPER ADMIN','warning'));brand.addEventListener('click',()=>onNavigate?.('/platform/admin'));const right=el(doc,'div','uw-platform-admin__header-actions');const who=el(doc,'div','uw-platform-actor');who.append(el(doc,'strong','',state.actor?.displayName||'Super Admin'),el(doc,'small','','Markaziy platforma vakolati'));right.append(createButton({label:'Foydalanuvchi portaliga',variant:'ghost',size:'sm',onClick:()=>onNavigate?.('/platform/app')},doc),who,createButton({label:'Chiqish',variant:'ghost',size:'sm',onClick:onLogout},doc));h.append(brand,right);return h;}
function adminNav(doc,active,onNavigate){const nav=el(doc,'nav','uw-platform-admin__nav');nav.setAttribute('aria-label','Super Admin bo‘limlari');for(const [id,label,href] of ADMIN_NAV){const a=el(doc,'a',id===active?'is-active':'',label);a.href=href;a.addEventListener('click',(e)=>{e.preventDefault?.();onNavigate?.(href);});nav.append(a);}return nav;}
function pageHead(doc,title,subtitle,action=null){const row=el(doc,'div','uw-platform-page-head');const copy=el(doc,'div');copy.append(el(doc,'h1','',title),el(doc,'p','',subtitle));row.append(copy);if(action)row.append(action);return row;}
function inlineState(doc,status,{loading='Yuklanmoqda…',empty='',error='Ma’lumot yuklanmadi.',retry=null}={}){if(status==='loading'||status==='idle')return createStatePanel({kind:'loading',title:loading,message:'Serverdan haqiqiy ma’lumot olinmoqda.'},doc);if(status==='error')return createStatePanel({kind:'error',title:error,message:'Server so‘rovi bajarilmadi.',actionLabel:retry?'Qayta urinish':'',onAction:retry||undefined},doc);if(status==='ready'&&empty)return createStatePanel({kind:'empty',title:empty,message:'Hozircha yozuv yo‘q.'},doc);return null;}
function stat(doc,label,value,meta=''){const n=el(doc,'article','uw-platform-stat');n.append(el(doc,'small','',label),el(doc,'strong','',value));if(meta)n.append(el(doc,'span','',meta));return n;}
function openExternal(url){const safe=safeUrl(url);if(safe)globalThis.open?.(safe,'_blank','noopener,noreferrer');}

function dashboardView(doc,state,onNavigate,controller){const wrap=el(doc,'div','uw-platform-page');wrap.append(pageHead(doc,'Platforma boshqaruvi','Faqat serverdagi haqiqiy platforma KPI va diqqat talab qiladigan holatlar.'));const p=inlineState(doc,state.dashboardStatus,{loading:'Dashboard yuklanmoqda',error:'Dashboard yuklanmadi',retry:()=>controller.loadDashboard()});if(p){wrap.append(p);return wrap;}const d=state.dashboard||{};const grid=el(doc,'div','uw-platform-stat-grid uw-platform-admin-kpis');grid.append(stat(doc,'Faol do‘konlar',Number(d.activeShopsCount||0)),stat(doc,'Yangi arizalar',Number(d.newRequestsCount||0)),stat(doc,'7 kunda tugaydi',Number(d.expiringSoonCount||0)),stat(doc,'Muzlatilgan',Number(d.expiredCount||0)),stat(doc,'Ochiq support',Number(d.supportOpenCount||0)),stat(doc,'Ownerlar',Number(d.totalUsersCount||0)));wrap.append(grid);const two=el(doc,'div','uw-platform-admin-grid');const attention=el(doc,'section','uw-platform-card');attention.append(el(doc,'h2','',"Diqqat talab qiladi"));const items=list(d.attentionItems);if(!items.length)attention.append(el(doc,'p','uw-muted','Hozircha shoshilinch holat yo‘q.'));else for(const item of items.slice(0,30)){const b=el(doc,'button','uw-platform-admin-row');b.type='button';const target=item.requestId?`/platform/admin/requests/${encodeURIComponent(item.requestId)}`:item.ticketId?`/platform/admin/support/${encodeURIComponent(item.ticketId)}`:item.shopId?`/platform/admin/shops/${encodeURIComponent(item.shopId)}`:'/platform/admin';b.addEventListener('click',()=>onNavigate?.(target));const cp=el(doc,'span','uw-platform-admin-row__copy');cp.append(el(doc,'strong','',item.label||item.type||'Holat'),el(doc,'small','',item.detail||''));b.append(badge(doc,String(item.type||'').replaceAll('_',' '),item.type==='GRACE_EXPIRED'?'danger':'warning'),cp);attention.append(b);}two.append(attention);const recent=el(doc,'section','uw-platform-card');recent.append(el(doc,'h2','',"Yangi do‘konlar"));for(const s of list(d.recentShops).slice(0,10)){const b=el(doc,'button','uw-platform-admin-row');b.type='button';b.addEventListener('click',()=>onNavigate?.(`/platform/admin/shops/${encodeURIComponent(s.id)}`));const cp=el(doc,'span','uw-platform-admin-row__copy');cp.append(el(doc,'strong','',s.public_code||s.id),el(doc,'small','',dateTime(s.created_at||s.createdAt)));b.append(cp,badge(doc,statusLabel(s.status),statusTone(s.status)));recent.append(b);}if(!list(d.recentShops).length)recent.append(el(doc,'p','uw-muted',"Do‘kon yo‘q."));two.append(recent);wrap.append(two);return wrap;}

