function lifecycleForm(doc,state,controller){const s=state.lifecycleSettings||{};const form=el(doc,'form','uw-platform-admin-settings-form');const retention=nameControl(doc.createElement('input'),'Ma’lumot saqlash muddati (kun)');retention.type='number';retention.min='1';retention.max='365';retention.value=s.retentionDays??30;const label=nameControl(doc.createElement('input'),'Support tugmasi nomi');label.value=s.supportLabel||'';label.placeholder='Support tugmasi matni';const url=nameControl(doc.createElement('input'),'Support URL');url.value=s.supportUrl||'';url.placeholder='Support URL';const auto=doc.createElement('input');auto.type='checkbox';auto.checked=s.autoFreezeOnExpiry!==false;const autoLabel=el(doc,'label','uw-platform-admin-check');autoLabel.append(auto,el(doc,'span','','Muddat tugaganda avtomatik muzlatish'));form.append(el(doc,'label','uw-field-label','Ma’lumot saqlash muddati (kun)'),retention,el(doc,'label','uw-field-label','Support nomi'),label,el(doc,'label','uw-field-label','Support URL'),url,autoLabel,createButton({label:'Lifecycle’ni saqlash'},doc));form.addEventListener('submit',e=>{e.preventDefault?.();controller.saveLifecycleSettings({...s,retentionDays:Number(retention.value),supportLabel:label.value,supportUrl:url.value,autoFreezeOnExpiry:auto.checked});});return form;}
function paymentCardForm(doc,state,controller){const s=state.paymentInfo||{};const form=el(doc,'form','uw-platform-admin-settings-form');const number=nameControl(doc.createElement('input'),'Karta raqami');number.value=s.cardNumber||'';number.placeholder='Karta raqami';const holder=nameControl(doc.createElement('input'),'Karta egasi');holder.value=s.cardHolder||'';holder.placeholder='Karta egasi';const active=doc.createElement('input');active.type='checkbox';active.checked=s.isActive!==false;const lab=el(doc,'label','uw-platform-admin-check');lab.append(active,el(doc,'span','','Faol'));form.append(number,holder,lab,createButton({label:'Kartani saqlash'},doc));form.addEventListener('submit',e=>{e.preventDefault?.();controller.savePaymentInfo({cardNumber:number.value,cardHolder:holder.value,isActive:active.checked});});return form;}
function paymentMethodForm(doc,row,controller){const form=el(doc,'form','uw-platform-admin-method-form');const type=nameControl(doc.createElement('select'),'To‘lov usuli turi');for(const v of ['CLICK','PAYME','PAYNET']){const o=doc.createElement('option');o.value=v;o.textContent=v;o.selected=v===String(row?.methodType||'CLICK').toUpperCase();type.append(o);}const name=nameControl(doc.createElement('input'),'To‘lov usuli nomi');name.value=row?.displayName||'';name.placeholder='Ko‘rinadigan nom';const url=nameControl(doc.createElement('input'),'To‘lov URL');url.value=row?.paymentUrl||'';url.placeholder='https://...';const sort=nameControl(doc.createElement('input'),'To‘lov usuli tartibi');sort.type='number';sort.value=row?.sortOrder??0;const active=doc.createElement('input');active.type='checkbox';active.checked=row?.isActive!==false;const lab=el(doc,'label','uw-platform-admin-check');lab.append(active,el(doc,'span','','Faol'));form.append(type,name,url,sort,lab,createButton({label:row?'Saqlash':'Usul qo‘shish',size:'sm'},doc));form.addEventListener('submit',e=>{e.preventDefault?.();controller.savePaymentMethod({id:row?.id,methodType:type.value,displayName:name.value,paymentUrl:url.value,sortOrder:sort.value,isActive:active.checked});});return form;}
function notificationForm(doc,row,controller){const form=el(doc,'form','uw-platform-admin-notification-form');const body=nameControl(doc.createElement('textarea'),'Avtomatik xabar matni');body.value=row?.body||'';body.placeholder='Xabar matni';const image=nameControl(doc.createElement('input'),'Avtomatik xabar rasmi URL');image.value=row?.imageUrl||'';image.placeholder='https://... rasm URL (ixtiyoriy)';const active=doc.createElement('input');active.type='checkbox';active.checked=row?.isActive!==false;const lab=el(doc,'label','uw-platform-admin-check');lab.append(active,el(doc,'span','','Faol'));const actions=el(doc,'div','uw-platform-inline-actions');actions.append(createButton({label:'Saqlash',size:'sm'},doc),createButton({label:'Sinov yuborish',variant:'secondary',size:'sm',type:'button',onClick:()=>controller.sendTestNotification(row.type)},doc));form.append(el(doc,'strong','',row.type||'TEMPLATE'),body,image,lab,actions);form.addEventListener('submit',e=>{e.preventDefault?.();controller.saveNotificationTemplate({type:row.type,body:body.value,imageUrl:image.value,isActive:active.checked});});return form;}
function settingsView(doc,state,controller){const wrap=el(doc,'div','uw-platform-page');wrap.append(pageHead(doc,'Platforma sozlamalari','Lifecycle, obuna to‘lovi va avtomatik xabarlar. Secret credentiallar bu sahifada saqlanmaydi.',createButton({label:'Platform botni sozlash',variant:'secondary',onClick:()=>{if(globalThis.confirm?.('Platform bot webhook/menu konfiguratsiyasi yangilansinmi?')===false)return;controller.setupPlatformBot();}},doc)));const p=inlineState(doc,state.settingsStatus,{loading:'Sozlamalar yuklanmoqda',error:'Sozlamalar yuklanmadi',retry:()=>controller.loadSettings()});if(p){wrap.append(p);return wrap;}const grid=el(doc,'div','uw-platform-admin-grid');const life=el(doc,'section','uw-platform-card');life.append(el(doc,'h2','',"Do‘kon lifecycle"),lifecycleForm(doc,state,controller));const card=el(doc,'section','uw-platform-card');card.append(el(doc,'h2','',"Karta orqali to‘lov"),paymentCardForm(doc,state,controller));grid.append(life,card);wrap.append(grid);const methods=el(doc,'section','uw-platform-card');methods.append(el(doc,'h2','',"Tashqi to‘lov havolalari"),paymentMethodForm(doc,null,controller));for(const m of state.paymentMethods)methods.append(paymentMethodForm(doc,m,controller));wrap.append(methods);const notifications=el(doc,'section','uw-platform-card');notifications.append(el(doc,'h2','',"Telegram avtomatik xabarlari"));for(const t of state.notificationTemplates)notifications.append(notificationForm(doc,t,controller));if(!state.notificationTemplates.length)notifications.append(el(doc,'p','uw-muted','Xabar shablonlari topilmadi.'));wrap.append(notifications);return wrap;}

export function createPlatformAdminView({controller,state=controller?.getState?.()||{},section='overview',params={},onNavigate,onSignedOut}={},documentRef){const doc=getDocument(documentRef);if(!controller)throw new TypeError('controller kerak');const root=el(doc,'div','uw-platform-admin uw-root');root.dataset.feature='platform-admin';root.append(adminHeader(doc,state,{onNavigate,onLogout:async()=>{const r=await controller.signOut();if(r.ok)onSignedOut?.();}}));if(state.status==='loading'||state.status==='idle'){root.append(createStatePanel({kind:'loading',title:'Super Admin tekshirilmoqda',message:'Markaziy platforma vakolati serverda tekshirilmoqda.'},doc));return {element:root};}if(state.status==='error'){root.append(createStatePanel({kind:'error',title:'Platforma yuklanmadi',message:state.error?.message||'Server bilan ulanishda xato.',actionLabel:'Qayta urinish',onAction:()=>controller.load()},doc));return {element:root};}if(state.status==='forbidden'||state.isSuperAdmin!==true){root.append(createStatePanel({kind:'permission',title:'Super Admin vakolati kerak',message:'Do‘kon OWNER/MANAGER/STAFF roli markaziy platforma Super Admin huquqini bermaydi.',actionLabel:'Platforma portaliga qaytish',onAction:()=>onNavigate?.('/platform/app')},doc));return {element:root};}
  const body=el(doc,'div','uw-platform-admin__body');body.append(adminNav(doc,section,onNavigate));const main=el(doc,'main','uw-platform-admin__main');main.id='uw-main-content';if(state.notice)main.append(createStatePanel({kind:state.notice.kind==='error'?'error':state.notice.kind==='warning'?'warning':'success',title:state.notice.kind==='error'?'Amal bajarilmadi':state.notice.kind==='warning'?'Eslatma':'Bajarildi',message:state.notice.message},doc));if(section==='shops')main.append(shopsView(doc,state,onNavigate,controller,params));else if(section==='requests')main.append(requestsView(doc,state,onNavigate,controller,params));else if(section==='support')main.append(supportView(doc,state,onNavigate,controller,params));else if(section==='tariffs')main.append(tariffsView(doc,state,controller));else if(section==='analytics')main.append(analyticsView(doc,state,controller));else if(section==='settings')main.append(settingsView(doc,state,controller));else main.append(dashboardView(doc,state,onNavigate,controller));body.append(main);root.append(body);return {element:root};}
